  1 | /**
  2 |  * 🦙 Llama Player — useGoogleDrive Hook
  3 |  *
  4 |  * Hook React para gerenciar autenticação, navegação e listagem
  5 |  * de arquivos do Google Drive.
  6 |  */
  7 | 
  8 | import { useState, useCallback, useEffect, useRef } from "react";
  9 | import {
 10 |   driveService,
 11 |   type DriveState,
 12 |   type DriveItem,
 13 |   type DriveFolder,
 14 |   type DriveFile,
 15 |   isAudioFile,
 16 | } from "../services/googleDrive";
 17 | import type { Track } from "../types";
 18 | 
 19 | // ID do Cliente OAuth — o usuário precisa configurar no .env
 20 | const CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID || "";
 21 | 
 22 | const initialState: DriveState = {
 23 |   isAuthenticated: false,
 24 |   isLoading: false,
 25 |   user: null,
 26 |   currentFolder: null,
 27 |   breadcrumbs: [],
 28 |   items: [],
 29 |   error: null,
 30 | };
 31 | 
 32 | export function useGoogleDrive() {
 33 |   const [state, setState] = useState<DriveState>(initialState);
 34 |   const serviceInitialized = useRef(false);
 35 | 
 36 |   /**
 37 |    * Tenta login silencioso ao montar (se houver token salvo).
 38 |    */
 39 |   useEffect(() => {
 40 |     if (!CLIENT_ID) {
 41 |       setState((prev) => ({
 42 |         ...prev,
 43 |         error:
 44 |           "VITE_GOOGLE_CLIENT_ID não configurado. Crie um arquivo .env com seu Client ID do Google Cloud.",
 45 |       }));
 46 |       return;
 47 |     }
 48 | 
 49 |     const init = async () => {
 50 |       try {
 51 |         await driveService.initialize(CLIENT_ID);
 52 |         serviceInitialized.current = true;
 53 | 
 54 |         const loggedIn = await driveService.trySilentLogin(CLIENT_ID);
 55 |         if (loggedIn) {
 56 |           const user = await driveService.getUserInfo();
 57 |           setState((prev) => ({
 58 |             ...prev,
 59 |             isAuthenticated: true,
 60 |             user,
 61 |             isLoading: false,
 62 |             error: null,
 63 |           }));
 64 |           // Carrega a raiz do Drive
 65 |           await loadFolder(null);
 66 |         } else {
 67 |           setState((prev) => ({ ...prev, isLoading: false }));
 68 |         }
 69 |       } catch (err: any) {
 70 |         console.error("[Llama Player] Erro na inicialização do Drive:", err);
 71 |         setState((prev) => ({
 72 |           ...prev,
 73 |           isLoading: false,
 74 |           error: err.message || "Erro ao inicializar Google Drive",
 75 |         }));
 76 |       }
 77 |     };
 78 | 
 79 |     init();
 80 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 81 |   }, []);
 82 | 
 83 |   /**
 84 |    * Faz login com OAuth popup.
 85 |    */
 86 |   const login = useCallback(async () => {
 87 |     if (!serviceInitialized.current) {
 88 |       try {
 89 |         await driveService.initialize(CLIENT_ID);
 90 |         serviceInitialized.current = true;
 91 |       } catch (err: any) {
 92 |         setState((prev) => ({
 93 |           ...prev,
 94 |           error: err.message || "Erro ao inicializar",
 95 |         }));
 96 |         return;
 97 |       }
 98 |     }
 99 | 
100 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
101 | 
102 |     try {
103 |       const success = await driveService.login();
104 |       if (success) {
105 |         const user = await driveService.getUserInfo();
106 |         setState((prev) => ({
107 |           ...prev,
108 |           isAuthenticated: true,
109 |           user,
110 |           isLoading: false,
111 |           error: null,
112 |         }));
113 |         await loadFolder(null);
114 |       } else {
115 |         setState((prev) => ({
116 |           ...prev,
117 |           isLoading: false,
118 |           error: "Login cancelado ou falhou",
119 |         }));
120 |       }
121 |     } catch (err: any) {
122 |       setState((prev) => ({
123 |         ...prev,
124 |         isLoading: false,
125 |         error: err.message || "Erro ao fazer login",
126 |       }));
127 |     }
128 |   }, []);
129 | 
130 |   /**
131 |    * Faz logout.
132 |    */
133 |   const logout = useCallback(async () => {
134 |     try {
135 |       await driveService.logout();
136 |     } catch {
137 |       // Ignora
138 |     }
139 |     setState({ ...initialState });
140 |   }, []);
141 | 
142 |   /**
143 |    * Navega para uma pasta do Drive.
144 |    */
145 |   const loadFolder = useCallback(async (folder: DriveFolder | null) => {
146 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
147 | 
148 |     try {
149 |       const items = await driveService.listFiles(folder?.id ?? null);
150 | 
151 |       setState((prev) => {
152 |         const breadcrumbs = folder
153 |           ? [...prev.breadcrumbs, folder]
154 |           : [];
155 |         return {
156 |           ...prev,
157 |           currentFolder: folder,
158 |           breadcrumbs,
159 |           items,
160 |           isLoading: false,
161 |           error: null,
162 |         };
163 |       });
164 |     } catch (err: any) {
165 |       setState((prev) => ({
166 |         ...prev,
167 |         isLoading: false,
168 |         error: err.message || "Erro ao carregar pasta",
169 |       }));
170 |     }
171 |   }, []);
172 | 
173 |   /**
174 |    * Navega para uma pasta (entra nela).
175 |    */
176 |   const navigateToFolder = useCallback(
177 |     async (folder: DriveFolder) => {
178 |       await loadFolder(folder);
179 |     },
180 |     [loadFolder]
181 |   );
182 | 
183 |   /**
184 |    * Navega para o breadcrumb (volta).
185 |    */
186 |   const navigateToBreadcrumb = useCallback(
187 |     async (index: number) => {
188 |       const target =
189 |         index === -1
190 |           ? null
191 |           : state.breadcrumbs[index];
192 | 
193 |       setState((prev) => ({
194 |         ...prev,
195 |         breadcrumbs: index === -1 ? [] : prev.breadcrumbs.slice(0, index + 1),
196 |       }));
197 | 
198 |       await loadFolder(target);
199 |     },
200 |     [state.breadcrumbs, loadFolder]
201 |   );
202 | 
203 |   /**
204 |    * Sobe um nível na hierarquia de pastas.
205 |    */
206 |   const goUp = useCallback(async () => {
207 |     const len = state.breadcrumbs.length;
208 |     if (len === 0) return;
209 |     await navigateToBreadcrumb(len - 2);
210 |   }, [state.breadcrumbs.length, navigateToBreadcrumb]);
211 | 
212 |   /**
213 |    * Converte um DriveFile em Track para o player.
214 |    */
215 |   const driveFileToTrack = useCallback((file: DriveFile): Track => {
216 |     const nameWithoutExt = file.name.replace(/\.[^/.]+$/, "");
217 |     return {
218 |       id: `drive-${file.id}`,
219 |       title: nameWithoutExt,
220 |       duration: file.duration || 0,
221 |       src: driveService.getStreamUrl(file.id),
222 |       driveFileId: file.id,
223 |     };
224 |   }, []);
225 | 
226 |   /**
227 |    * Converte múltiplos DriveFiles em Tracks.
228 |    */
229 |   const driveFilesToTracks = useCallback(
230 |     (files: DriveFile[]): Track[] => {
231 |       return files.filter(isAudioFile).map(driveFileToTrack);
232 |     },
233 |     [driveFileToTrack]
234 |   );
235 | 
236 |   /**
237 |    * Obtém apenas os arquivos de áudio da listagem atual.
238 |    */
239 |   const getAudioFiles = useCallback((): DriveFile[] => {
240 |     return state.items.filter(isAudioFile) as DriveFile[];
241 |   }, [state.items]);
242 | 
243 |   /**
244 |    * Busca arquivos de áudio no Drive.
245 |    */
246 |   const searchAudio = useCallback(async (query: string) => {
247 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
248 |     try {
249 |       const files = await driveService.searchAudio(query);
250 |       // Cria itens falsos para exibir na lista
251 |       const items: DriveItem[] = files;
252 |       setState((prev) => ({
253 |         ...prev,
254 |         items,
255 |         isLoading: false,
256 |         error: null,
257 |       }));
258 |     } catch (err: any) {
259 |       setState((prev) => ({
260 |         ...prev,
261 |         isLoading: false,
262 |         error: err.message || "Erro na busca",
263 |       }));
264 |     }
265 |   }, []);
266 | 
267 |   return {
268 |     state,
269 |     login,
270 |     logout,
271 |     navigateToFolder,
272 |     navigateToBreadcrumb,
273 |     goUp,
274 |     driveFileToTrack,
275 |     driveFilesToTracks,
276 |     getAudioFiles,
277 |     searchAudio,
278 |     CLIENT_ID,
279 |   };
280 | }
